def team_of(m: Mesh, agent: str) -> tuple[str, str] | None:
    row = m.conn.execute(
        "SELECT c.campaign_id, c.name FROM agents a JOIN campaigns c ON c.campaign_id=a.campaign_id "
        "WHERE a.agent_id=? AND c.status='active'", (agent,)).fetchone()
    return (row[0], row[1]) if row else None


def team_named(m: Mesh, name: str) -> tuple[str, str] | None:
    row = m.conn.execute("SELECT campaign_id, name FROM campaigns WHERE (name=? OR campaign_id=?) AND status='active' "
                         "ORDER BY rowid DESC LIMIT 1", (name, name)).fetchone()
    return (row[0], row[1]) if row else None


def members(m: Mesh, campaign_id: str) -> list[str]:
    return [r[0] for r in m.conn.execute("SELECT agent_id FROM agents WHERE campaign_id=? ORDER BY agent_id",
                                         (campaign_id,))]


